constraints:
1 ≤ N ≤ 10^{5}
1 ≤ A[i] ≤ 10^{5}
1 ≤ q ≤ 10^{4}

expected time complexity: O(q*logN)
expected auxiliary space: O(N)

standard_solution_code:
class segtree:

	def __init__(self, n):
		self.st = [0] * (4 * n)
		self.size = n - 1

	def update(self, x, value, m, l=0, h=-1, i=0):
		if h == -1:
			h = self.size
		if l > h or l > x or h < x:
			return
		if l == h:
			if l == x:
				self.st[i] = value
			return
		mid = (l + h) // 2
		self.update(x, value, m - 1, l, mid, 2 * i + 1)
		self.update(x, value, m - 1, mid + 1, h, 2 * i + 2)
		if m % 2:
			self.st[i] = self.st[2 * i + 1] | self.st[2 * i + 2]
		else:
			self.st[i] = self.st[2 * i + 1] ^ self.st[2 * i + 2]

	def query(self, x, y, l=0, h=-1, i=0):
		if h == -1:
			h = self.size
		if l > y or h < x:
			return 0
		if l >= x and h <= y:
			return self.st[i]
		if l == h:
			return 0
		mid = (l + h) // 2
		left = self.query(x, y, l, mid, 2 * i + 1)
		right = self.query(x, y, mid + 1, h, 2 * i + 2)
		return left + right

class Solution:

	def left(self, N, A, q, query):
		m = 1
		x = 0
		while m < N:
			m *= 2
			x += 1
		if m != N:
			for i in range(m - N):
				A.append(0)
		st = segtree(m)
		for i in range(m):
			st.update(i, A[i], x)
		ans = []
		for (i, v) in query:
			if i < m:
				st.update(i, v, x)
				ans.append('\n' + str(st.query(0, m - 1)))
			else:
				ans.append('\n-1')
		ans[0] = ans[0].strip()
		return ans
